TopNav.css = "\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   HEADER  \u2014  full-width sticky bar\n   (TopNav is flex:1; Search/Darkmode/ReaderMode\n    appear as siblings on the right)\n   \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\nheader {\n  position: fixed !important;\n  top: 0 !important;\n  left: 0 !important;\n  z-index: 200 !important;\n  display: flex !important;\n  align-items: center !important;\n  margin: 0 !important;\n  width: 100% !important;\n  max-width: 100% !important;\n  box-sizing: border-box !important;\n  height: 56px !important;\n  min-height: 56px !important;\n  background: var(--light) !important;\n  border-bottom: 0 !important;\n  box-shadow: none !important;\n  transition: transform 0.24s ease, background-color 0.18s ease !important;\n  will-change: transform;\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n  padding: 0 !important;\n}\n\nheader.header-hidden {\n  transform: translateY(calc(-100% + 8px)) !important;\n}\n\nheader.header-hidden:hover,\nheader.header-hidden:focus-within {\n  transform: translateY(0) !important;\n}\n\n.site-header-shell > .search,\n.site-header-shell > .github-link,\n.site-header-shell > .rss-link,\n.site-header-shell > .darkmode,\n.site-header-shell > .readermode {\n  flex: 0 0 auto !important;\n}\n\n.site-header-shell > .search {\n  margin-left: 0 !important;\n  margin-right: 0 !important;\n}\n\n.site-header-shell > .search .search-button {\n  height: 2rem !important;\n  width: 2rem !important;\n  border-radius: 6px !important;\n  background: transparent !important;\n}\n\n.site-header-shell > .darkmode,\n.site-header-shell > .readermode {\n  margin-left: 0 !important;\n}\n\n/* \u2500\u2500 TopNav takes all remaining width \u2500\u2500 */\n.top-nav {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: clamp(0.75rem, 2vw, 2rem);\n  height: 100%;\n}\n\n/* \u2500\u2500 Brand \u2500\u2500 */\n.nav-brand {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  text-decoration: none;\n  flex-shrink: 0;\n  margin-right: 0;\n  transition: opacity 0.15s ease;\n}\n.nav-brand:hover { opacity: 0.75; }\n\n.nav-brand-logo {\n  width: 30px;\n  height: 30px;\n  border-radius: 5px;\n  object-fit: contain;\n  display: block;\n}\n\nhtml[saved-theme=\"dark\"] .nav-brand-logo {\n  filter: brightness(0) invert(1);\n}\n\n.nav-brand-name {\n  font-family: var(--titleFont);\n  font-size: 0.88rem;\n  font-weight: 600;\n  color: var(--dark);\n  white-space: nowrap;\n  letter-spacing: -0.01em;\n}\n\n/* \u2500\u2500 Nav links row \u2500\u2500 */\n.nav-links {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: clamp(0.12rem, 0.7vw, 0.55rem);\n  height: 100%;\n  min-width: 0;\n  margin-left: auto;\n}\n\n/* \u2500\u2500 Shared item style \u2500\u2500 */\n.nav-item {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  padding: 5px clamp(8px, 1vw, 12px);\n  border-radius: 6px;\n  font-family: var(--titleFont);\n  font-size: 0.88rem;\n  font-weight: 600;\n  color: var(--dark);\n  text-decoration: none;\n  white-space: nowrap;\n  transition: color 0.15s ease, background 0.15s ease, opacity 0.15s ease;\n  background: none;\n  border: none;\n  cursor: pointer;\n  line-height: 1;\n  height: 32px;\n}\n.nav-item:hover,\n.nav-group.open > .nav-item  { color: var(--dark); background: var(--highlight); }\n.nav-item.active,\n.nav-group.active > .nav-item { color: var(--dark); }\n\n.nav-links:has(.nav-item:hover) .nav-item,\n.nav-links:has(.nav-item:focus-visible) .nav-item {\n  color: var(--dark);\n  opacity: 0.35;\n  background: transparent;\n}\n\n.nav-links:has(.nav-item:hover) .nav-item:hover,\n.nav-links:has(.nav-item:focus-visible) .nav-item:focus-visible,\n.nav-links:has(.nav-group.open) .nav-group.open > .nav-item {\n  color: var(--dark);\n  opacity: 1;\n  background: var(--highlight);\n}\n\n/* \u2500\u2500 Chevron \u2500\u2500 */\n.nav-chevron {\n  flex-shrink: 0;\n  transition: transform 0.2s ease;\n}\n.nav-group.open > .nav-trigger .nav-chevron {\n  transform: rotate(180deg);\n}\n\n/* \u2500\u2500 Group wrapper (trigger + dropdown) \u2500\u2500 */\n.nav-group {\n  position: relative;\n  height: 100%;\n  display: flex;\n  align-items: center;\n}\n\n/* \u2500\u2500 Mega dropdown panel \u2500\u2500 */\n.nav-mega {\n  position: absolute;\n  top: calc(100% + 6px);\n  left: 50%;\n  transform: translateX(-50%) translateY(-6px);\n  width: 400px;\n  background: var(--light);\n  border: 1px solid var(--lightgray);\n  border-radius: 12px;\n  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12), 0 2px 8px rgba(0, 0, 0, 0.06);\n  padding: 8px;\n  opacity: 0;\n  pointer-events: none;\n  transition: opacity 0.18s ease, transform 0.18s ease;\n  z-index: 300;\n}\n.nav-group.open .nav-mega {\n  opacity: 1;\n  pointer-events: auto;\n  transform: translateX(-50%) translateY(0);\n}\n\nhtml[saved-theme=\"dark\"] .nav-mega {\n  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.50), 0 2px 8px rgba(0, 0, 0, 0.30);\n  border-color: rgba(255, 255, 255, 0.10);\n}\n\n/* \u2500\u2500 Mega grid \u2500\u2500 */\n.mega-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 4px;\n}\n\n/* \u2500\u2500 Mega row (each item) \u2500\u2500 */\n.mega-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 10px 10px;\n  border-radius: 8px;\n  text-decoration: none;\n  transition: background 0.15s ease;\n}\n.mega-row:hover { background: var(--highlight); }\n\n.mega-icon {\n  width: 34px;\n  height: 34px;\n  border-radius: 7px;\n  background: var(--lightgray);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-family: var(--codeFont);\n  font-size: 0.65rem;\n  font-weight: 700;\n  color: var(--darkgray);\n  flex-shrink: 0;\n  letter-spacing: 0;\n}\n\n.mega-text {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n}\n\n.mega-title {\n  font-family: var(--titleFont);\n  font-size: 0.82rem;\n  font-weight: 600;\n  color: var(--dark);\n  white-space: nowrap;\n}\n\n.mega-desc {\n  font-size: 0.72rem;\n  color: var(--gray);\n  white-space: nowrap;\n}\n\n/* \u2500\u2500 \"Browse all\" footer \u2500\u2500 */\n.mega-footer {\n  display: block;\n  margin-top: 6px;\n  padding: 8px 10px;\n  border-top: 1px solid var(--lightgray);\n  font-size: 0.75rem;\n  color: var(--gray);\n  text-decoration: none;\n  border-radius: 0 0 6px 6px;\n  transition: color 0.15s ease;\n}\n.mega-footer:hover { color: var(--dark); }\n\n/* \u2500\u2500 Make the in-flow page header gap sensible \u2500\u2500 */\n.page-header {\n  margin-top: 0 !important;\n  padding-top: 56px !important;\n}\n\n/* \u2500\u2500 Mobile \u2500\u2500 */\n@media (max-width: 600px) {\n  .nav-brand-name { display: none; }\n  .nav-links {\n    overflow-x: auto;\n    scrollbar-width: none;\n    justify-content: flex-start;\n  }\n  .nav-links::-webkit-scrollbar { display: none; }\n  .nav-item { padding: 5px 9px; font-size: 0.76rem; }\n  .nav-mega { width: 320px; }\n  .mega-grid { grid-template-columns: 1fr; }\n}\n";
TopNav.afterDOMLoaded = "\n(function () {\n  function initTopNav() {\n    var header = document.querySelector(\"header\");\n\n    // \u2500\u2500 close all groups \u2500\u2500\n    function closeAll() {\n      document.querySelectorAll(\".nav-group.open\").forEach(function (g) {\n        g.classList.remove(\"open\");\n        var btn = g.querySelector(\".nav-trigger\");\n        if (btn) btn.setAttribute(\"aria-expanded\", \"false\");\n      });\n    }\n\n    // \u2500\u2500 toggle a group \u2500\u2500\n    document.querySelectorAll(\".nav-group\").forEach(function (group) {\n      var trigger = group.querySelector(\".nav-trigger\");\n      if (!trigger) return;\n\n      var handler = function (e) {\n        e.stopPropagation();\n        var isOpen = group.classList.contains(\"open\");\n        closeAll();\n        if (!isOpen) {\n          group.classList.add(\"open\");\n          trigger.setAttribute(\"aria-expanded\", \"true\");\n        }\n      };\n      trigger.addEventListener(\"click\", handler);\n      window.addCleanup(function () { trigger.removeEventListener(\"click\", handler); });\n    });\n\n    // \u2500\u2500 close on outside click / nav event \u2500\u2500\n    var docHandler = function () { closeAll(); };\n    document.addEventListener(\"click\", docHandler);\n    window.addCleanup(function () { document.removeEventListener(\"click\", docHandler); });\n\n    if (header) {\n      var lastY = window.scrollY || 0;\n      var ticking = false;\n\n      function thresholdY() {\n        var content = document.querySelector(\"article.popover-hint\") || document.querySelector(\"article\");\n        if (!content) return header.offsetHeight * 2;\n        return Math.max(0, content.getBoundingClientRect().top + window.scrollY - header.offsetHeight);\n      }\n\n      function hasOpenOverlay() {\n        return Boolean(\n          document.querySelector(\".nav-group.open\") ||\n          document.querySelector(\".search-container.active\") ||\n          header.matches(\":hover\") ||\n          header.matches(\":focus-within\"),\n        );\n      }\n\n      function updateHeader() {\n        ticking = false;\n        var currentY = window.scrollY || 0;\n        var delta = currentY - lastY;\n        var beyondContentTop = currentY >= thresholdY();\n\n        if (currentY <= 4 || delta < -4 || hasOpenOverlay()) {\n          header.classList.remove(\"header-hidden\");\n        } else if (delta > 4 && beyondContentTop) {\n          header.classList.add(\"header-hidden\");\n        }\n\n        lastY = currentY;\n      }\n\n      function requestHeaderUpdate() {\n        if (ticking) return;\n        ticking = true;\n        window.requestAnimationFrame(updateHeader);\n      }\n\n      function revealNearTop(event) {\n        if (event.clientY <= 12) {\n          header.classList.remove(\"header-hidden\");\n        }\n      }\n\n      header.classList.remove(\"header-hidden\");\n      window.addEventListener(\"scroll\", requestHeaderUpdate, { passive: true });\n      window.addEventListener(\"resize\", requestHeaderUpdate);\n      document.addEventListener(\"mousemove\", revealNearTop);\n      header.addEventListener(\"mouseenter\", requestHeaderUpdate);\n      header.addEventListener(\"mouseleave\", requestHeaderUpdate);\n      window.addCleanup(function () {\n        window.removeEventListener(\"scroll\", requestHeaderUpdate);\n        window.removeEventListener(\"resize\", requestHeaderUpdate);\n        document.removeEventListener(\"mousemove\", revealNearTop);\n        header.removeEventListener(\"mouseenter\", requestHeaderUpdate);\n        header.removeEventListener(\"mouseleave\", requestHeaderUpdate);\n        header.classList.remove(\"header-hidden\");\n      });\n    }\n  }\n\n  document.addEventListener(\"nav\", initTopNav);\n})();\n";
